            if (done && !b.disabled) { b.disabled = true; b.setAttribute("aria-disabled", "true"); b.__eqilClosed = true; }
            else if (!done && b.__eqilClosed) { b.disabled = false; b.removeAttribute("aria-disabled"); b.__eqilClosed = false; }
        }
    }

    function doSelect(sel, roundChanged) {
