            out.gap = ds.last.gap;
            out.find = ds.last.find;
            out.ni = ds.last.ni;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, period, g) {
            if (this.ROUND_OF[g] <= period) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _fedDd() {
            var c = this.C;
            var loss = 0;
            var i;
            for (i = 0; i < this.BOOK_KEYS.length; i++) { loss += this.BOOK[this.BOOK_KEYS[i]] * this.FED_RATE[this.BOOK_KEYS[i]]; }
            loss = loss + c.OTHER_LOSS;
            return (loss - c.PPNR_FED) * (1 - c.TAX) / c.RWA0 * 100.0;
        }

        _bankDd(s, m) {
            var c = this.C;
            var other = 0;
            var i;
            for (i = 0; i < this.BOOK_KEYS.length; i++) {
                if (this.BOOK_KEYS[i] !== 'office') { other += this.BOOK[this.BOOK_KEYS[i]] * this.FED_RATE[this.BOOK_KEYS[i]]; }
            }
            other = other + c.OTHER_LOSS;
            var loss = other * this.S_K[s] + this.BOOK.office * this.M_OFF[m] * this.S_OFF[s];
            return (loss - this.S_PPNR[s]) * (1 - c.TAX) / c.RWA0 * 100.0;
        }

        _state(dec, period) {
            var c = this.C;
            var a = {};
            var i;
            for (i = 0; i < this.KEYS.length; i++) { a[this.KEYS[i]] = this._active(dec, period, this.KEYS[i]); }
            var t = 1 - c.TAX;
            var D = this.DIV[a.div2], B = this.BB[a.bb2];
            var ddf = this._fedDd();
            var ddb = this._bankDd(a.scen1, a.model1);
            var scbOwn = Math.max(c.FLOOR, ddb + D / c.RWA0 * 100.0);
            var scb = Math.max(c.FLOOR, ddf + D / c.RWA0 * 100.0);
            var req = c.MIN + scb;
            var ev = period >= 4;
            var cost = (this.S_COST[a.scen1] + this.M_COST[a.model1] + this.G_COST[a.gov3]) * t;
            var pref = a.resp3 === 'pref';
            var prefdiv = pref ? c.PREF * c.PREF_RATE / 2.0 : 0.0;
            var bs = ev ? a.bs4 : this.REF.bs4;
            var evLoss = ev ? (this.BOOK.office * c.EVENT_RATE + this.M_CATCH[a.model1]) : 0.0;
            var ni27 = c.NI27 - cost - prefdiv + (this.B_PL_Q4[bs] - evLoss) * t;
            var nih1 = c.NIH1 + this.B_PL_H1[bs] * t - (ev ? this.B_OFF[bs] * c.OFF_H1 * t : 0.0) - (pref ? prefdiv : 0.0);
            var rwaQ4 = c.RWA0 + c.RWA_YTD + this.B_RWA_Q4[bs];
            var rwaQ2 = rwaQ4 + this.B_RWA_H1[bs];
            var d4 = ev ? a.dist4 : this.REF.dist4;
            var divq4 = D / 4.0 * ((d4 === 'cutdiv') ? 0.5 : 1.0);
            var divh1 = D / 2.0 * ((d4 === 'cutdiv') ? 0.5 : 1.0);
            var r3 = a.resp3;
            var m3q3 = 1.0, m3 = 1.0;
            if (r3 === 'trim') {
                var xq4 = c.CET0 + c.NI27 - cost - prefdiv + this.B_PL_Q4.grow * t - c.DIV_H1 - D / 2.0 - c.BB_H1;
                var rq4 = c.RWA0 + c.RWA_YTD + this.B_RWA_Q4.grow;
                var rq2 = rq4 + this.B_RWA_H1.grow;
                var tgt = (req + c.MB) / 100.0;
                var lim1 = 2.0 * (xq4 - tgt * rq4);
                var lim2 = xq4 + c.NIH1 + this.B_PL_H1.grow * t - D / 2.0 - tgt * rq2;
                var bnew = this._clamp(Math.min(lim1, lim2), 0.0, B);
                m3q3 = (B > 0) ? bnew / B : 0.0;
                m3 = (B > 0) ? bnew / B : 0.0;
            } else if (r3 === 'recon') {
                m3q3 = 0.0;
                m3 = 1.0;
            }
            var m4q4 = (d4 === 'cont' || d4 === 'accel') ? 1.0 : 0.0;
            var m4h1 = (d4 === 'cont' || d4 === 'accel') ? 1.0 : 0.0;
            var bbq3 = B / 4.0 * m3q3;
            var bbq4 = B / 4.0 * m3 * m4q4 + ((d4 === 'accel') ? c.ACCEL : 0.0);
            var bbh1 = B / 2.0 * m3 * m4h1;
            var cetQ4 = c.CET0 + ni27 - (c.DIV_H1 + D / 4.0 + divq4) - (c.BB_H1 + bbq3 + bbq4);
            var cetQ2 = cetQ4 + nih1 - divh1 - bbh1;
            var ratioQ4 = cetQ4 / rwaQ4 * 100.0;
            var ratioQ2 = cetQ2 / rwaQ2 * 100.0;
            var low = Math.min(ratioQ4, ratioQ2);
            var head = low - req;
            var returned = D / 4.0 + divq4 + divh1 + bbq3 + bbq4 + bbh1;
            var pen = 0.0;
            if (period >= 2 && a.div2 === 'cut') { pen += c.PEN_DIVCUT2; }
            if (period >= 3) {
                pen += (r3 === 'trim') ? c.PEN_CUT * (B - (bbq3 + B / 4.0 * m3 + B / 2.0 * m3)) : 0.0;
                pen += (r3 === 'recon') ? c.PEN_RECON : 0.0;
            }
            if (ev && d4 === 'cutdiv') { pen += c.PEN_DIVCUT; }
            if (ev && ratioQ4 < req) { pen += c.PEN_BREACH; }
            pen += c.K_THIN * Math.max(0.0, c.MB - head);
            var value = returned - pen;
            var gap0 = ddf - ddb;
            var gap = (period >= 3) ? gap0 * (1.0 - this.G_CLOSE[a.gov3]) : gap0;
            var err = Math.max(gap, 0.0) + 0.5 * Math.max(-gap, 0.0);
            var f = this.S_F[a.scen1] + this.M_F[a.model1];
            if (period >= 3) {
                f += this.G_F[a.gov3];
                if (r3 === 'recon' && !(a.model1 === 'doc' && a.scen1 === 'own')) { f += 0.5; }
            }
            var breach = 0.0;
            if (ev && (d4 === 'cont' || d4 === 'accel') && low < req && (bbq4 + bbh1) > 0) { breach = req - low; }
            return { a: a, ddf: ddf, ddb: ddb, scb: scb, scbOwn: scbOwn, req: req, ni27: ni27, nih1: nih1, low: low, head: head,
                     ratioQ4: ratioQ4, ratioQ2: ratioQ2, returned: returned, pen: pen, value: value, gap: gap, err: err, f: f, breach: breach };
        }

        _components(m) {
            var c = this.C;
            var h = this._clamp((m.head - c.H_LO) / (c.H_HI - c.H_LO), 0, 1);
            var r = this._clamp((m.value - c.R_LO) / (c.R_HI - c.R_LO), 0, 1);
            var ac = this._clamp((c.A_LO - m.err) / (c.A_LO - c.A_HI), 0, 1);
            var s = this._clamp(1.0 - m.f / c.S_MAX, 0, 1);
            var e = this._clamp((m.ni27 - c.E_LO) / (c.E_HI - c.E_LO), 0, 1);
            return [h, r, ac, s, e];
        }

        _capOf(m) {
            var c = this.C;
            if (m.breach <= 0) { return 100.0; }
            return Math.max(c.CAP_MIN, c.CAP0 - c.CAP_K * m.breach);
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._state(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_H, c.W_R, c.W_A, c.W_S, c.W_E];
            var live = this.LIVE[period];
            var tw = 0, num = 0;
            var i;
            for (i = 0; i < 5; i++) { tw += w[i] * live[i]; }
            for (i = 0; i < 5; i++) { num += w[i] * live[i] * comps[i]; }
            var score = 100.0 * num / tw;
            score = this._clamp(score, 0, 100);
            var cap = this._capOf(m);
            score = Math.min(score, cap);
            m.cap = cap;
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            var capMin = 100.0;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
                capMin = Math.min(capMin, r.m.cap);
            }
            var total = this._clamp(this._jsround(num / den), 0, 100);
            total = Math.min(total, this._jsround(capMin));
            return total;
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'en';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'es') ? '.' : ',';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 ? '-' : '') + out;
        }

        _fmtM(n) {
            var body = this._fmtInt(n);
            if (this._lang() === 'es') { return body + ' M$'; }
            return (body.charAt(0) === '-') ? ('-$' + body.slice(1) + 'm') : ('$' + body + 'm');
        }

        _two(n) {
            var s = (Math.round(n * 100) / 100).toFixed(2);
            if (this._lang() === 'es') { s = s.replace('.', ','); }
            return s;
        }

        _pct(n) {
            return (this._lang() === 'es') ? (this._two(n) + ' %') : (this._two(n) + '%');
        }

        _pp(n) {
            var s = (n > 0 ? '+' : '') + this._two(n);
            return (this._lang() === 'es') ? (s + ' p. p.') : (s + ' pp');
        }

        _findFmt(n) {
            var s = String(n);
            if (this._lang() === 'es') { s = s.replace('.', ','); }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(g) {
                var el = document.getElementById(g + period);
                if (el && k[g + period]) { el.value = k[g + period]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var sH = ds.scbHistory || [];
            var lH = ds.lowHistory || [];
            var hH = ds.headHistory || [];
            var vH = ds.valueHistory || [];
            var fH = ds.findHistory || [];
            var nH = ds.niHistory || [];
            var n = lH.length;
            this._set('valueDisplay', n ? (this._pct(lH[n - 1]) + ' · ' + this._pp(hH[n - 1]) + ' ' + this._t('txt_head')) : '-');
            this._set('metDisplay', n ? (this._pct(sH[n - 1]) + ' · ' + this._findFmt(fH[n - 1]) + ' ' + this._t('txt_find')) : '-');
            this._set('credDisplay', n ? (this._fmtM(vH[n - 1]) + ' ' + this._t('txt_ret') + ' · ' + this._fmtM(nH[n - 1]) + ' ' + this._t('txt_ni')) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var d = this._flat(state, p);
            var m = this._state(d, p);
            var a = m.a;
            if (m.breach > 0) { return this._t('hint_breach'); }
            if (p === 1 && a.scen1 !== 'own') { return this._t('hint_scen'); }
            if (p === 1 && a.model1 !== 'doc') { return this._t('hint_model'); }
            if (p === 2 && a.bb2 !== 'mid') { return this._t('hint_bb'); }
            if (p === 2 && a.div2 !== 'hold') { return this._t('hint_div'); }
            if (p === 3 && a.resp3 !== 'trim') { return this._t('hint_resp'); }
            if (p === 3 && a.gov3 !== 'bench') { return this._t('hint_gov'); }
            if (p === 4 && a.bs4 !== 'crt') { return this._t('hint_bs'); }
            if (p === 4 && a.dist4 !== 'cont') { return this._t('hint_dist'); }
            return null;
        }

        getChartConfig() {
            return {
                valueChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'CET1 low point (%)', data: [], borderColor: '#34508a', backgroundColor: 'rgba(52,80,138,0.12)', borderWidth: 2 },
                            { label: 'Requirement (%)', data: [], borderColor: '#8a4b0f', backgroundColor: 'rgba(138,75,15,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 12 } } }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#34508a', backgroundColor: 'rgba(52,80,138,0.35)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var lowHistory = ds.lowHistory || [];
            var reqHistory = ds.reqHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = lowHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                valueChart: {
                    labels: labels,
                    datasets: [
                        { data: lowHistory.slice(), label: this._t('chart_low') },
                        { data: reqHistory.slice(), label: this._t('chart_req') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var pct = function(v) { return self._pct(v); };
            var pp = function(v) { return self._pp(v); };
            var money = function(v) { return self._fmtM(v); };
            var fnd = function(v) { return self._findFmt(v); };
            return [
                { key: 'results.scb', label: 'Stress capital buffer (%)', i18nKey: 'col_scb', formatter: pct },
                { key: 'results.low', label: 'CET1 low point (%)', i18nKey: 'col_low', formatter: pct },
                { key: 'results.head', label: 'Headroom over the requirement (pp)', i18nKey: 'col_head', formatter: pp },
                { key: 'results.value', label: 'Capital returned, net', i18nKey: 'col_value', formatter: money },
                { key: 'results.gap', label: 'Projection gap vs the Fed (pp)', i18nKey: 'col_gap', formatter: pp },
                { key: 'results.find', label: 'Supervisory findings', i18nKey: 'col_find', formatter: fnd },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._state(d, mm);
            var a = m.a;
            var composite = this._composite(state);
            var insights = [];
            insights.push(this._t({ fed: 'fb_sc_fed', own: 'fb_sc_own', base: 'fb_sc_base', vendor: 'fb_sc_vendor' }[a.scen1]));
            insights.push(this._t({ asis: 'fb_mo_asis', doc: 'fb_mo_doc', judg: 'fb_mo_judg', neg: 'fb_mo_neg' }[a.model1]));
            if (mm >= 2) {
                insights.push(this._t({ cut: 'fb_dv_cut', hold: 'fb_dv_hold', up10: 'fb_dv_up10', up20: 'fb_dv_up20' }[a.div2]));
                insights.push(this._t({ none: 'fb_bb_none', small: 'fb_bb_small', mid: 'fb_bb_mid', large: 'fb_bb_large' }[a.bb2]));
            }
            if (mm >= 3) {
                insights.push(this._t({ keep: 'fb_rp_keep', trim: 'fb_rp_trim', recon: 'fb_rp_recon', pref: 'fb_rp_pref' }[a.resp3]));
                insights.push(this._t({ ignore: 'fb_gv_ignore', match: 'fb_gv_match', bench: 'fb_gv_bench', redev: 'fb_gv_redev' }[a.gov3]));
            }
            if (mm >= 4) {
                insights.push(this._t({ cont: 'fb_ds_cont', pause: 'fb_ds_pause', cutdiv: 'fb_ds_cutdiv', accel: 'fb_ds_accel' }[a.dist4]));
                insights.push(this._t({ grow: 'fb_bs_grow', hold: 'fb_bs_hold', crt: 'fb_bs_crt', sell: 'fb_bs_sell' }[a.bs4]));
            }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                low: Math.round(m.low * 100) / 100,
                head: Math.round(m.head * 100) / 100,
                value: Math.round(m.value * 1000),
                gap: Math.round(m.gap * 100) / 100,
                find: m.f,
                ni: Math.round(m.ni27 * 1000),
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2489-cm">'
                + '<div class="ej2489-cm-score">' + score + '<span class="ej2489-cm-max">/100</span></div>'
                + '<div class="ej2489-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2489-cm-kpis">'
                + '<div class="ej2489-cm-kpi">' + this._t('cm_kpi_low') + ' <strong>' + this._pct(s.low || 0) + '</strong></div>'
                + '<div class="ej2489-cm-kpi">' + this._t('cm_kpi_head') + ' <strong>' + this._pp(s.head || 0) + '</strong></div>'
                + '<div class="ej2489-cm-kpi">' + this._t('cm_kpi_value') + ' <strong>' + this._fmtM(s.value || 0) + '</strong></div>'
                + '<div class="ej2489-cm-kpi">' + this._t('cm_kpi_gap') + ' <strong>' + this._pp(s.gap || 0) + '</strong></div>'
                + '<div class="ej2489-cm-kpi">' + this._t('cm_kpi_find') + ' <strong>' + this._findFmt(s.find || 0) + '</strong></div>'
                + '<div class="ej2489-cm-kpi">' + this._t('cm_kpi_ni') + ' <strong>' + this._fmtM(s.ni || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2489-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ej2489-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getTranslations() {
            return {
        es: {
            bb2_large: `1.600 millones de dólares (lo que se prometió)`,
            bb2_mid: `800 millones de dólares (el ritmo del último programa)`,
            bb2_none: `Ninguna: conservar el capital hasta junio`,
            bb2_small: `400 millones de dólares (medio programa anterior)`,
            bs4_crt: `Transferencia sintética de riesgo sobre 6.000 millones de préstamos de calidad`,
            bs4_grow: `Seguir creciendo en préstamos según el presupuesto: los clientes están ahí`,
            bs4_hold: `Congelar el crecimiento de préstamos hasta dejar atrás las pérdidas`,
            bs4_sell: `Vender 2.000 millones de préstamos de oficinas al 85 % y salir del problema`,
            btn_next: `Confirmar decisiones y pasar a la siguiente ronda`,
            chart_low: `Punto mínimo de CET1 (%)`,
            chart_req: `Requisito (%)`,
            chart_score: `Puntuación de la ronda`,
            cm_debrief: `Lo que ha decidido vuestro equipo:`,
            cm_kpi_find: `Observaciones supervisoras`,
            cm_kpi_gap: `Diferencia con la Fed`,
            cm_kpi_head: `Margen sobre el requisito`,
            cm_kpi_low: `Punto mínimo de CET1`,
